# Python 3 examples. Indentation and spaces inside strings are significant.
def normalized_labels(values):
    labels = []
    for value in values:
        if value == "":
            continue
        labels.append(value.replace("  ", "|", 1).strip())
    return labels

def words(text, explicit=False):
    if explicit:
        return text.split(" ")
    return text.split()

